import { useId } from "react";

import { cn } from "@/lib/utils";

export type AgentProviderIconKey =
  | "claude"
  | "codex"
  | "copilot"
  | "kimi"
  | "opencode"
  | "qoder"
  | "zcode";

type AgentProviderIconProps = {
  iconKey: AgentProviderIconKey;
  className?: string;
};

export function agentProviderIconKey(
  providerId?: string | null,
  providerName?: string | null,
): AgentProviderIconKey | null {
  const value = `${providerId ?? ""} ${providerName ?? ""}`.toLowerCase();
  if (/\bqoder|qodercli/.test(value)) return "qoder";
  if (/\bclaude|anthropic/.test(value)) return "claude";
  if (/\bcopilot|github copilot/.test(value)) return "copilot";
  if (/\bcodex|openai/.test(value)) return "codex";
  if (/\bopencode|open code/.test(value)) return "opencode";
  if (/\bkimi|moonshot/.test(value)) return "kimi";
  if (/\bzcode|z\.ai|bigmodel/.test(value)) return "zcode";
  return null;
}

